-- 101_project_variation_closeout.sql
BEGIN;
CREATE TABLE IF NOT EXISTS public.project_variation_closeout_versions(id uuid PRIMARY KEY,project_id bigint NOT NULL REFERENCES public.projects(id)ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status text NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),total_proposed_count integer NOT NULL CHECK(total_proposed_count>=0),approved_count integer NOT NULL CHECK(approved_count>=0),rejected_count integer NOT NULL CHECK(rejected_count>=0),pending_count integer NOT NULL CHECK(pending_count>=0),final_approved_variation_value numeric(24,2)NOT NULL CHECK(final_approved_variation_value>=0),currency_code text NOT NULL CHECK(currency_code~'^[A-Z]{3}$'),main_reasons jsonb NOT NULL CHECK(jsonb_typeof(main_reasons)='array'),work_groups_with_most_changes jsonb NOT NULL CHECK(jsonb_typeof(work_groups_with_most_changes)='array'),variation_explanation text NOT NULL CHECK(btrim(variation_explanation)<>''AND char_length(variation_explanation)<=3000),created_by uuid NOT NULL REFERENCES auth.users(id)ON DELETE RESTRICT,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(project_id,version_number));
CREATE UNIQUE INDEX IF NOT EXISTS project_variation_closeout_one_confirmed_idx ON public.project_variation_closeout_versions(project_id)WHERE status='CONFIRMED';
CREATE OR REPLACE FUNCTION private.prevent_variation_closeout_mutation()RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$BEGIN RAISE EXCEPTION'PROJECT_VARIATION_CLOSEOUT_IMMUTABLE'USING ERRCODE='55000';END;$$;DROP TRIGGER IF EXISTS project_variation_closeout_immutable ON public.project_variation_closeout_versions;CREATE TRIGGER project_variation_closeout_immutable BEFORE UPDATE OR DELETE ON public.project_variation_closeout_versions FOR EACH ROW EXECUTE FUNCTION private.prevent_variation_closeout_mutation();
ALTER TABLE public.project_variation_closeout_versions ENABLE ROW LEVEL SECURITY;DROP POLICY IF EXISTS project_variation_closeout_select ON public.project_variation_closeout_versions;CREATE POLICY project_variation_closeout_select ON public.project_variation_closeout_versions FOR SELECT TO authenticated USING(public.can_access_project(project_id));REVOKE ALL ON TABLE public.project_variation_closeout_versions FROM PUBLIC,anon,authenticated,service_role;GRANT SELECT ON TABLE public.project_variation_closeout_versions TO authenticated;
CREATE OR REPLACE FUNCTION public.save_project_variation_closeout(p_project_id bigint,p_closeout_id uuid,p_variation_explanation text,p_confirm boolean,p_client_request_id uuid)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE u uuid:=auth.uid();role_name text;req public.write_command_requests%ROWTYPE;proposed integer;approved integer;rejected integer;pending integer;approved_value numeric;currency text;reasons jsonb;groups jsonb;version_no integer;state text;result jsonb;
BEGIN SELECT upper(role)INTO role_name FROM public.profiles WHERE id=u;IF u IS NULL OR role_name NOT IN('PM','ADMIN')OR public.can_write_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_VARIATION_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;IF p_closeout_id IS NULL OR p_client_request_id IS NULL OR btrim(COALESCE(p_variation_explanation,''))=''OR char_length(p_variation_explanation)>3000 THEN RAISE EXCEPTION'INVALID_PROJECT_VARIATION_CLOSEOUT'USING ERRCODE='22023';END IF;INSERT INTO public.write_command_requests(actor_id,operation,client_request_id,project_id)VALUES(u,'project_closeout.variation.save',p_client_request_id,p_project_id)ON CONFLICT(actor_id,operation,client_request_id)DO NOTHING;SELECT*INTO req FROM public.write_command_requests WHERE actor_id=u AND operation='project_closeout.variation.save'AND client_request_id=p_client_request_id;IF req.response IS NOT NULL THEN RETURN req.response||jsonb_build_object('idempotentReplay',true);END IF;IF EXISTS(SELECT 1 FROM public.project_variation_closeout_versions WHERE project_id=p_project_id AND status='CONFIRMED')THEN RAISE EXCEPTION'PROJECT_VARIATION_CLOSEOUT_ALREADY_CONFIRMED'USING ERRCODE='55000';END IF;
SELECT count(*),count(*)FILTER(WHERE status='APPROVED'),count(*)FILTER(WHERE status='REJECTED'),count(*)FILTER(WHERE status NOT IN('APPROVED','REJECTED')),COALESCE(sum(approved_amount)FILTER(WHERE status='APPROVED'),0)INTO proposed,approved,rejected,pending,approved_value FROM public.project_variations WHERE project_id=p_project_id;SELECT COALESCE((SELECT currency_code FROM public.project_tender_awards WHERE project_id=p_project_id ORDER BY awarded_at DESC LIMIT 1),(SELECT currency_code FROM public.projects WHERE id=p_project_id),'USD')INTO currency;
SELECT COALESCE(jsonb_agg(jsonb_build_object('reasonCode',x.reason_code,'variationCount',x.variation_count,'proposedValue',x.proposed_value,'approvedValue',x.approved_value)ORDER BY x.variation_count DESC,x.reason_code),'[]')INTO reasons FROM(SELECT reason_code,count(*)variation_count,sum(proposed_amount)proposed_value,COALESCE(sum(approved_amount)FILTER(WHERE status='APPROVED'),0)approved_value FROM public.project_variations WHERE project_id=p_project_id GROUP BY reason_code)x;SELECT COALESCE(jsonb_agg(jsonb_build_object('workGroupId',x.work_group_id,'workGroupLabel',x.label,'variationCount',x.variation_count,'approvedValue',x.approved_value)ORDER BY x.variation_count DESC,x.label),'[]')INTO groups FROM(SELECT v.work_group_id,g.label,count(*)variation_count,COALESCE(sum(v.approved_amount)FILTER(WHERE v.status='APPROVED'),0)approved_value FROM public.project_variations v JOIN public.work_ontology_work_groups g ON g.ontology_version_id=v.ontology_version_id AND g.id=v.work_group_id WHERE v.project_id=p_project_id GROUP BY v.work_group_id,g.label)x;
SELECT COALESCE(max(version_number),0)+1 INTO version_no FROM public.project_variation_closeout_versions WHERE project_id=p_project_id;state:=CASE WHEN COALESCE(p_confirm,false)THEN'CONFIRMED'ELSE'DRAFT'END;INSERT INTO public.project_variation_closeout_versions VALUES(p_closeout_id,p_project_id,version_no,state,proposed,approved,rejected,pending,approved_value,currency,reasons,groups,btrim(p_variation_explanation),u,now());result:=jsonb_build_object('variationCloseoutId',p_closeout_id,'versionNumber',version_no,'status',state,'totalProposedCount',proposed,'approvedCount',approved,'rejectedCount',rejected,'pendingCount',pending,'finalApprovedVariationValue',approved_value,'currencyCode',currency,'reasonCount',jsonb_array_length(reasons),'workGroupCount',jsonb_array_length(groups));UPDATE public.write_command_requests SET response=result,completed_at=now()WHERE id=req.id;RETURN result||jsonb_build_object('idempotentReplay',false);END;$$;
CREATE OR REPLACE FUNCTION public.get_project_variation_closeout(p_project_id bigint)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER STABLE SET search_path=public AS $$DECLARE x public.project_variation_closeout_versions%ROWTYPE;BEGIN IF auth.uid()IS NULL OR public.can_access_project(p_project_id)IS NOT TRUE THEN RAISE EXCEPTION'PROJECT_VARIATION_CLOSEOUT_FORBIDDEN'USING ERRCODE='42501';END IF;SELECT*INTO x FROM public.project_variation_closeout_versions WHERE project_id=p_project_id ORDER BY version_number DESC LIMIT 1;RETURN jsonb_build_object('projectId',p_project_id,'hasCloseout',x.id IS NOT NULL,'closeout',CASE WHEN x.id IS NULL THEN NULL ELSE jsonb_build_object('variationCloseoutId',x.id,'versionNumber',x.version_number,'status',x.status,'totalProposedCount',x.total_proposed_count,'approvedCount',x.approved_count,'rejectedCount',x.rejected_count,'pendingCount',x.pending_count,'finalApprovedVariationValue',x.final_approved_variation_value,'currencyCode',x.currency_code,'mainReasons',x.main_reasons,'workGroupsWithMostChanges',x.work_groups_with_most_changes,'variationExplanation',x.variation_explanation,'createdAt',x.created_at)END);END;$$;
REVOKE ALL ON FUNCTION private.prevent_variation_closeout_mutation()FROM PUBLIC,anon,authenticated,service_role;REVOKE ALL ON FUNCTION public.save_project_variation_closeout(bigint,uuid,text,boolean,uuid),public.get_project_variation_closeout(bigint)FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.save_project_variation_closeout(bigint,uuid,text,boolean,uuid),public.get_project_variation_closeout(bigint)TO authenticated;
COMMIT;
